/// Returns true if there is a value in the slot to be consumed
///
/// # Safety
///
/// To maintain safety, the caller must ensure:
///
/// * No concurrent access to the slot.
pub(crate) fn has_value(&self, slot_index: usize) -> bool {
    let block_start = self.header.start_index;
    let slot_offset = SLOT_MASK & slot_index;
    let distance = slot_index.wrapping_sub(block_start);
    let ready_bits = self.header.ready_slots.load(Acquire);

    if BLOCK_CAP == distance {
        // The requested slot is located within the next block: the ready
        // bits of the current block do not describe it. If the next block
        // has not been allocated yet, the slot cannot hold a value.
        let next_block = self.header.next.load(Acquire);
        match NonNull::new(next_block as *mut Block<T>) {
            None => false,
            Some(next) => {
                let next_ready_bits = unsafe { next.as_ref().header.ready_slots.load(Acquire) };
                is_ready(next_ready_bits, slot_offset)
            }
        }
    } else {
        // The requested slot is located within the current block.
        is_ready(ready_bits, slot_offset)
    }
}

