use tokio::sync::mpsc;

#[tokio::main]
async fn main() {
    let (sender, mut receiver) = mpsc::channel(33);

    for value in 1..257 {
        sender.send(value).await.unwrap();
        receiver.recv().await.unwrap();
        assert!(receiver.is_empty(), "{value}. len: {}", receiver.len());
    }
    println!("bounded ok");

    let (sender, mut receiver) = mpsc::unbounded_channel::<u8>();
    for _ in 0..257 {
        sender.send(0).unwrap();
        receiver.recv().unwrap();
        assert!(receiver.is_empty(), "unbounded len: {}", receiver.len());
    }
    println!("unbounded ok");

    let (sender, mut receiver) = mpsc::channel::<u8>(1);
    for _ in 0..257 {
        sender.send(0).await.unwrap();
        receiver.recv().await.unwrap();
        assert!(receiver.is_empty(), "cap1 len: {}", receiver.len());
    }
    println!("cap1 ok");

    // also check non-empty still reported correctly
    let (sender, mut receiver) = mpsc::channel(33);
    for value in 0..257 {
        sender.send(value).await.unwrap();
        assert!(!receiver.is_empty());
        receiver.recv().await.unwrap();
        assert!(receiver.is_empty());
    }
    println!("nonempty ok");

    // tx closed with pending values
    let (sender, mut receiver) = mpsc::channel(33);
    for v in 0..40 { sender.send(v).unwrap(); }
    drop(sender);
    assert!(!receiver.is_empty());
    while receiver.recv().await.is_some() {}
    assert!(receiver.is_empty());
    println!("closed ok");
}
EOF
